      const head=document.createElement('div');head.className='comment-card-header';const name=document.createElement('strong');name.textContent='You';const time=document.createElement('time');time.textContent=new Date(comment.time).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});head.append(name,time);
