    const sections=data.tabs.map(t=>`<section><h1>${escapeHTML(t.name)}</h1>${t.html}</section>`).join('');const html=`<!DOCTYPE html><html><head><meta charset="utf-8"><title>${escapeHTML(data.title)}</title><style>body{font:16px/1.65 Arial,sans-serif;max-width:780px;margin:40px auto;padding:0 25px;color:#202124}section{padding-bottom:45px;border-bottom:1px solid #eee}img{max-width:100%}table{border-collapse:collapse;width:100%}td,th{border:1px solid #ddd;padding:9px;text-align:left}blockquote{border-left:3px solid #4285f4;padding-left:16px;color:#53647d}</style></head><body>${sections}</body></html>`;download(name+'.html',html,'text/html;charset=utf-8');
