  function renameTab(tabId){const tab=data.tabs.find(t=>t.id===tabId);if(!tab)return;showDialog('Rename tab',box=>{const input=dialogInput(box,'Tab name',tab.name);const row=document.createElement('div');row.className='dialog-row';row.append(dialogButton('Cancel',()=>dialog.close(),false),dialogButton('Save',()=>{const v=input.value.trim();if(!v){input.focus();return;}tab.name=v;renderTabs();scheduleSave();dialog.close();}));box.append(row);setTimeout(()=>input.select(),0);});}
  function deleteTab(tabId){if(data.tabs.length===1){toast('Keep at least one tab in the document.');return;}const tab=data.tabs.find(t=>t.id===tabId);showDialog('Delete tab?',box=>{const p=document.createElement('p');p.textContent=`“${tab.name}” and its comments will be removed from this device.`;box.append(p);const row=document.createElement('div');row.className='dialog-row';row.append(dialogButton('Cancel',()=>dialog.close(),false),dialogButton('Delete',()=>{if(data.active===tabId){data.active=data.tabs.find(t=>t.id!==tabId).id;editor.innerHTML=currentTab().html;}data.tabs=data.tabs.filter(t=>t.id!==tabId);renderTabs();renderOutline();renderComments();wordCount();scheduleSave();dialog.close();},true));box.append(row);});}
  function showComments(focus=false){$('#comments-panel').hidden=false;if(focus)setTimeout(()=>$('#comment-text').focus(),0);}
