  function openLinkDialog(){const text=selectedText();showDialog('Insert link',box=>{const label=dialogInput(box,'Text to display',text,'Link text');const url=dialogInput(box,'Web address','','https://example.com');const row=document.createElement('div');row.className='dialog-row';row.append(dialogButton('Cancel',()=>dialog.close(),false),dialogButton('Insert',()=>{let href=url.value.trim();if(!href){url.focus();return;}if(!/^https?:\/\//i.test(href)&&!/^mailto:/i.test(href))href='https://'+href;try{const parsed=new URL(href);if(!['http:','https:','mailto:'].includes(parsed.protocol))throw Error();}catch{toast('Enter a valid web address.');url.focus();return;}dialog.close();restoreSelection();if(window.getSelection().toString()){document.execCommand('createLink',false,href);}else{document.execCommand('insertHTML',false,`<a href="${escapeHTML(href)}" target="_blank" rel="noopener noreferrer">${escapeHTML(label.value.trim()||href)}</a>`);}afterEdit();}));box.append(row);setTimeout(()=>url.focus(),0);});}
  function insertTable(){showDialog('Insert table',box=>{const rows=dialogInput(box,'Rows','3');const cols=dialogInput(box,'Columns','3');rows.type=cols.type='number';rows.min=cols.min='1';rows.max=cols.max='12';const row=document.createElement('div');row.className='dialog-row';row.append(dialogButton('Cancel',()=>dialog.close(),false),dialogButton('Insert',()=>{const r=Math.max(1,Math.min(12,Number(rows.value)||1)),c=Math.max(1,Math.min(12,Number(cols.value)||1));dialog.close();restoreSelection();const tr=Array.from({length:r},(_,ri)=>'<tr>'+Array.from({length:c},()=>ri===0?'<th><br></th>':'<td><br></td>').join('')+'</tr>').join('');document.execCommand('insertHTML',false,`<table><tbody>${tr}</tbody></table><p><br></p>`);afterEdit();}));box.append(row);});}
  function insertDate(){const date=new Date().toLocaleDateString(undefined,{year:'numeric',month:'long',day:'numeric'});runCommand('insertText',date);}
  function showVersions(){capture();showDialog('Version history',box=>{const p=document.createElement('p');p.textContent='Recent local snapshots for this tab. Restoring a snapshot replaces its current content.';box.append(p);const versions=data.versions.filter(v=>v.tabId===data.active);if(!versions.length){const e=document.createElement('p');e.textContent='No earlier versions yet. Versions appear as you edit.';box.append(e);return;}versions.forEach((v,i)=>{const row=document.createElement('div');row.className='version-row';const label=document.createElement('div');const d=document.createElement('strong');d.textContent=i===0?'Latest snapshot':'Earlier snapshot';const t=document.createElement('small');t.textContent=new Date(v.time).toLocaleString();label.append(d,t);const b=dialogButton('Restore',()=>{if(!confirm('Replace this tab with this earlier version?'))return;rememberVersion();editor.innerHTML=v.html;afterEdit();dialog.close();toast('Version restored');},false);row.append(label,b);box.append(row);});});}
  function showShare(){showDialog(`Share “${data.title}”`,box=>{box.innerHTML='<div class="share-person"><span class="avatar">S</span><div class="person-name">You<small>Local workspace</small></div><span class="owner">Owner</span></div><h3>General access</h3><div class="access-row">'+icon('lock')+'<div>Restricted<small>Only available in this browser on this device</small></div></div><p>Live sharing and Google Drive sync are not connected. Download a copy to send to someone.</p>';const row=document.createElement('div');row.className='dialog-row';row.append(dialogButton('Download copy',()=>exportDocument('html'),false),dialogButton('Done',()=>dialog.close()));box.append(row);});}
  function showWordCount(){const count=wordCount(),text=editor.innerText||'';showDialog('Word count',box=>{const stats=document.createElement('div');stats.className='word-stats';[['Words',count],['Characters',text.length],['Characters excluding spaces',text.replace(/\s/g,'').length]].forEach(([name,value])=>{const a=document.createElement('span'),b=document.createElement('span');a.textContent=name;b.textContent=value.toLocaleString();stats.append(a,b);});box.append(stats);const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.checked=!!data.showWordCount;check.onchange=()=>{data.showWordCount=check.checked;$('.status-bar').classList.toggle('show-word-count',check.checked);scheduleSave();};label.append(check,'Display word count while typing');box.append(label);const row=document.createElement('div');row.className='dialog-row';row.append(dialogButton('OK',()=>dialog.close()));box.append(row);});}

