  function setMode(editing){editor.contentEditable=String(editing);$('#mode-label').textContent=editing?'Editing':'Viewing';$('#mode').querySelector('[data-icon]').innerHTML=icon(editing?'pen':'eye');$('#mode').classList.toggle('viewing',!editing);document.querySelectorAll('.toolbar [data-command],#block,#font,#font-size,#text-color-button,#highlight,#insert-image,#link,#paint-format,#alignment,#line-spacing,#smaller,#larger').forEach(b=>b.disabled=!editing);}
  function selectedBlocks(){restoreSelection();const selection=getSelection();if(!selection.rangeCount)return[];const range=selection.getRangeAt(0);const blocks=[...editor.querySelectorAll('p,h1,h2,h3,h4,h5,h6,li,blockquote,td,th')].filter(el=>range.intersectsNode(el)&&!el.querySelector('p,h1,h2,h3,li'));if(blocks.length)return blocks;let node=selection.anchorNode?.nodeType===3?selection.anchorNode.parentElement:selection.anchorNode;if(node&&node!==editor&&editor.contains(node))return[node];document.execCommand('formatBlock',false,'p');return[selection.anchorNode?.parentElement].filter(el=>el&&el!==editor);}
