  function colorPalette(button,highlight=false){storeSelection();const r=button.getBoundingClientRect();openPopup([],r.left,r.bottom+6);const content=document.createElement('div');content.className='palette';content.innerHTML=`<div class="palette-heading">${highlight?'Highlight color':'Text color'}</div>`;const reset=document.createElement('button');reset.className='menu-item';reset.textContent=highlight?'None':'Automatic';reset.onclick=()=>{closeMenu();runCommand(highlight?'hiliteColor':'foreColor',highlight?'transparent':'#000000');};content.append(reset);const grid=document.createElement('div');grid.className='palette-grid';const colors=['#000000','#434343','#666666','#999999','#b7b7b7','#cccccc','#d9d9d9','#efefef','#f3f3f3','#ffffff','#980000','#ff0000','#ff9900','#ffff00','#00ff00','#00ffff','#4a86e8','#0000ff','#9900ff','#ff00ff','#e6b8af','#f4cccc','#fce5cd','#fff2cc','#d9ead3','#d0e0e3','#c9daf8','#cfe2f3','#d9d2e9','#ead1dc','#dd7e6b','#ea9999','#f9cb9c','#ffe599','#b6d7a8','#a2c4c9','#a4c2f4','#9fc5e8','#b4a7d6','#d5a6bd','#cc4125','#cc0000','#e69138','#f1c232','#6aa84f','#45818e','#3c78d8','#3d85c6','#674ea7','#a64d79','#a61c00','#990000','#b45f06','#bf9000','#38761d','#134f5c','#1155cc','#0b5394','#351c75','#741b47'];colors.forEach(color=>{const swatch=document.createElement('button');swatch.className='swatch';swatch.style.background=color;swatch.title=color;swatch.setAttribute('aria-label',`${highlight?'Highlight':'Text'} ${color}`);swatch.onclick=()=>{closeMenu();runCommand(highlight?'hiliteColor':'foreColor',color);if(!highlight)button.style.textDecorationColor=color;};grid.append(swatch);});content.append(grid);popup.append(content);}
  function toolFinder(){storeSelection();const r=$('#find').getBoundingClientRect();openPopup([],r.left,r.bottom+6);popup.style.width='340px';const wrap=document.createElement('div');wrap.innerHTML='<div class="tool-search">'+icon('search')+'<input aria-label="Search the menus" placeholder="Search the menus (Alt+/)"></div><div class="search-results"></div>';popup.append(wrap);const field=wrap.querySelector('input'),results=wrap.querySelector('.search-results');const actions=Object.entries(menuMap).flatMap(([menu,items])=>items.filter(x=>x[0]!=='divider').map(([label,action])=>({label,action,menu})));function render(){results.replaceChildren();const query=field.value.toLowerCase().trim();const matches=actions.filter(a=>a.label.toLowerCase().includes(query)).slice(0,9);matches.forEach(a=>{const b=document.createElement('button');b.className='menu-item';b.innerHTML='<span class="menu-label"></span><kbd></kbd>';b.firstChild.textContent=a.label;b.lastChild.textContent=a.menu;b.onclick=()=>{closeMenu();a.action();};results.append(b);});if(!matches.length){const p=document.createElement('div');p.className='search-empty';p.textContent='No matching tools';results.append(p);}}field.oninput=render;field.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();results.querySelector('button')?.click();}if(e.key==='ArrowDown'){e.preventDefault();results.querySelector('button')?.focus();}};render();field.focus();}
