  const shortcuts={'Undo':'Ctrl+Z','Redo':'Ctrl+Y','Cut':'Ctrl+X','Copy':'Ctrl+C','Paste':'Ctrl+V','Select all':'Ctrl+A','Find':'Ctrl+F','Find and replace':'Ctrl+H','Bold':'Ctrl+B','Italic':'Ctrl+I','Underline':'Ctrl+U','Link':'Ctrl+K','Comment':'Ctrl+Alt+M','Print':'Ctrl+P','Word count':'Ctrl+Shift+C','Clear formatting':'Ctrl+\\','Compact controls':'Ctrl+Shift+F','Search the menus':'Alt+/'};
