  function closeMenu(){popup.hidden=true;activeMenu=null;$('#menus').querySelectorAll('button').forEach(b=>{b.classList.remove('active');b.setAttribute('aria-expanded','false');});}
  function openPopup(items,x,y){popup.replaceChildren();popup.style.width='';items.forEach(item=>{const [label,action]=Array.isArray(item)?item:[item.label,item.action];if(label==='divider'||item.divider){const div=document.createElement('div');div.className='menu-divider';popup.append(div);return;}const btn=document.createElement('button');btn.className='menu-item';btn.type='button';btn.innerHTML='<span class="menu-icon">'+(menuIcons[label]?icon(menuIcons[label]):'')+'</span><span class="menu-label"></span><kbd></kbd>';btn.querySelector('.menu-label').textContent=label;btn.querySelector('kbd').textContent=shortcuts[label]||'';btn.addEventListener('click',()=>{closeMenu();action();});popup.append(btn);});popup.hidden=false;const width=320,height=Math.min(items.length*35+15,window.innerHeight*.7);popup.style.left=Math.max(8,Math.min(x,window.innerWidth-width-8))+'px';popup.style.top=Math.max(8,Math.min(y,window.innerHeight-height-8))+'px';}
