  $('#image-file').addEventListener('change',async e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Choose an image file.');return;}try{const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});const image=new Image();image.src=url;await image.decode();const canvas=document.createElement('canvas');const scale=Math.min(1,1200/image.width);canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const output=canvas.toDataURL('image/jpeg',.82);restoreSelection();document.execCommand('insertImage',false,output);afterEdit();toast('Image inserted');}catch{toast('Could not add that image.');}e.target.value='';});
  function setZoom(){const selected=$('#zoom').value;const pageWidth=parseFloat(getComputedStyle(document.documentElement).getPropertyValue('--page-width'))||816;const value=selected==='Fit'?Math.min(1.5,Math.max(.25,($('#canvas').clientWidth-64)/pageWidth)):Number.parseInt(selected,10)/100;editor.style.zoom=innerWidth<=720?'1':String(value);document.documentElement.style.setProperty('--document-zoom',innerWidth<=720?'1':String(value));$('.ruler').style.zoom=innerWidth<=720?'1':String(value);$('.status-right span').textContent=selected;}
