  $('#calendar').addEventListener('click',()=>openUtility('calendar'));$('#notes').addEventListener('click',()=>openUtility('notes'));$('#tasks').addEventListener('click',()=>openUtility('tasks'));$('#rail-add').addEventListener('click',()=>info('Side panel','Use Calendar to insert dates, Keep for local notes, Tasks for your checklist, Contacts for saved details, and Maps to look up places.'));$('#rail-hide').addEventListener('click',()=>{$('.side-rail').classList.toggle('rail-hidden');});
  titleInput.addEventListener('input',()=>{document.title=(titleInput.value||'Untitled document')+' — Docs';scheduleSave();});titleInput.addEventListener('blur',()=>{if(!titleInput.value.trim())titleInput.value='Untitled document';scheduleSave();});
  editor.addEventListener('input',()=>{rememberVersion();afterEdit();});editor.addEventListener('keyup',storeSelection);editor.addEventListener('mouseup',storeSelection);editor.addEventListener('pointerdown',()=>pendingFontSize=null);
  editor.addEventListener('paste',e=>{const html=e.clipboardData?.getData('text/html');if(!html)return;e.preventDefault();const parsed=new DOMParser().parseFromString(html,'text/html');parsed.querySelectorAll('script,style,iframe,object,embed,form,svg,math').forEach(n=>n.remove());parsed.querySelectorAll('*').forEach(n=>{[...n.attributes].forEach(a=>{if(a.name.startsWith('on')||a.name==='style'||(['href','src'].includes(a.name)&&/^(javascript|data:text\/html):/i.test(a.value)))n.removeAttribute(a.name);});});document.execCommand('insertHTML',false,parsed.body.innerHTML);afterEdit();});
  window.addEventListener('beforeunload',()=>save(true));
  titleInput.value=data.title;document.title=data.title+' — Docs';editor.innerHTML=currentTab().html;$('#star').classList.toggle('starred',data.starred);$('#star').style.color=data.starred?'#f9ab00':'';renderTabs();renderOutline();renderComments();wordCount();editor.classList.toggle('is-empty',!editor.innerText.trim());if(!localStorageAvailable)setSaveStatus('Storage unavailable — download a copy',true);
  initializeReferenceLayout();
  const mobileOutline=document.createElement('button');mobileOutline.className='mobile-outline-button';mobileOutline.type='button';mobileOutline.setAttribute('aria-label','Open document outline');mobileOutline.innerHTML=icon('panel');mobileOutline.addEventListener('click',toggleOutline);$('#canvas').prepend(mobileOutline);
  applyPageSetup();$('.status-bar').classList.toggle('show-word-count',!!data.showWordCount);
  popup.addEventListener('keydown',e=>{const buttons=[...popup.querySelectorAll('button')];const at=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp'].includes(e.key)&&at>=0){e.preventDefault();buttons[(at+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();}if(e.key==='Escape'){closeMenu();restoreSelection();}});
  document.addEventListener('keydown',e=>{const mod=e.ctrlKey||e.metaKey;if(e.altKey&&e.key==='/'){e.preventDefault();toolFinder();}if(mod&&e.key.toLowerCase()==='k'){e.preventDefault();openLinkDialog();}if(mod&&e.key.toLowerCase()==='h'){e.preventDefault();findReplace();}if(mod&&e.shiftKey&&e.key.toLowerCase()==='c'){e.preventDefault();showWordCount();}if(mod&&e.altKey&&e.key.toLowerCase()==='m'){e.preventDefault();addComment();}if(mod&&e.shiftKey&&e.key.toLowerCase()==='f'){e.preventDefault();$('#collapse').click();}if(mod&&e.key==='\\'){e.preventDefault();runCommand('removeFormat');}if(e.key==='Escape'&&paintStyle){paintStyle=null;$('#paint-format').classList.remove('paint-armed');editor.classList.remove('is-painting');}});
  editor.addEventListener('mouseup',()=>{if(!paintStyle||getSelection().isCollapsed)return;const style=paintStyle;paintStyle=null;storeSelection();runCommand('fontName',style.font);runCommand('foreColor',style.color);setFontSize(style.size);['bold','italic','underline'].forEach(command=>{if(document.queryCommandState(command)!==style[command])runCommand(command);});$('#paint-format').classList.remove('paint-armed');editor.classList.remove('is-painting');});
  editor.addEventListener('change',e=>{if(e.target.matches('input[type=checkbox]')){if(e.target.checked)e.target.setAttribute('checked','');else e.target.removeAttribute('checked');e.target.closest('li').dataset.checked=String(e.target.checked);afterEdit();}});
